fraction <- function(numerator,denominator) {
  if (denominator == 0) return("-")
  if (denominator < 0) {
    numerator <- -numerator
    denominator <- -denominator
  }
  a <- abs(numerator)
  b <- denominator
  while (b != 0) {
    remainder <- a %% b
    a <- b
    b <- remainder
  }
  paste0(sprintf("%.0f",numerator %/% a),"/",sprintf("%.0f",denominator %/% a))
}
confusion_matrix <- function(k) matrix(0L,k,k)
accumulate_confusion <- function(matrix,truth,prediction) {
  for (i in seq_along(truth)) matrix[truth[i],prediction[i]] <- matrix[truth[i],prediction[i]]+1L
  matrix
}
correct_count <- function(truth,prediction) sum(truth == prediction)
matrix_lines <- function(states,matrix) {
  width <- max(nchar(as.character(matrix)))
  padded <- function(value) paste0(strrep(" ",width-nchar(as.character(value))),value)
  lines <- paste0(" ",paste0(" ",vapply(states,padded,character(1)),collapse=""))
  for (i in seq_along(states)) lines <- c(
      lines,
      paste0(states[i],paste0(" ",vapply(matrix[i,],padded,character(1)),collapse=""))
  )
  lines
}
metric_lines <- function(states,matrix) {
  k <- length(states)
  rows <- rowSums(matrix)
  columns <- colSums(matrix)
  total <- sum(rows)
  correct <- sum(diag(matrix))
  expected <- sum(rows*columns)
  lines <- c(
      paste("ACCURACY",fraction(correct,total)),
      paste("KAPPA",fraction(total*correct-expected,total*total-expected))
  )
  for (i in seq_len(k)) {
    tp <- matrix[i,i]
    lines <- c(
        lines,
        paste(
            "STATE",
            states[i],
            "precision",
            fraction(tp,columns[i]),
            "recall",
            fraction(tp,rows[i]),
            "f1",
            fraction(2L*tp,columns[i]+rows[i])
        )
    )
  }
  lines
}
runs <- function(path) {
  result <- list()
  if (!length(path)) return(result)
  start <- 1L
  state <- path[1L]
  if (length(path) > 1L) for (t in seq.int(2L,length(path))) if (path[t] != state) {
    result[[length(result)+1L]] <- c(state,start,t-1L)
    start <- t
    state <- path[t]
  }
  result[[length(result)+1L]] <- c(state,start,length(path))
  result
}
regions_overlap <- function(a,b) a[1L] <= b[2L] && b[1L] <= a[2L]
region_counts <- function(predicted,truth) c(length(predicted),length(truth),
  sum(vapply(
      predicted,
      function(region) any(vapply(truth,function(other) regions_overlap(region,other),logical(1))),
      logical(1)
  )),
  sum(vapply(
      truth,
      function(region) any(vapply(predicted,function(other) regions_overlap(region,other),logical(1))),
      logical(1)
  )))
boundaries <- function(path) if (length(path) < 2L) integer() else which(head(path,-1L) != tail(path,-1L))+1L
boundary_counts <- function(predicted_path,true_path,tolerance) {
  predicted <- boundaries(predicted_path)
  truth <- boundaries(true_path)
  c(
      length(predicted),
      length(truth),
      sum(vapply(predicted,function(p) any(abs(p-truth) <= tolerance),logical(1))),
      sum(vapply(truth,function(t) any(abs(predicted-t) <= tolerance),logical(1)))
  )
}

ordered_sum <- function(values) {
  total <- 0
  for (value in values) total <- total+value
  total
}
normalize <- function(values) values/ordered_sum(values)
make_model <- function(name,states,symbols,missing,initial,transition,emission) {
  for (i in seq_len(nrow(transition))) {
    transition[i,] <- normalize(transition[i,])
    emission[i,] <- normalize(emission[i,])
  }
  list(
      name=name,
      states=states,
      symbols=symbols,
      missing=missing,
      initial=normalize(initial),
      transition=transition,
      emission=emission
  )
}
read_inputs <- function() {
  read_tokens <- function(name) strsplit(readLines(file.path("input",name))," ",fixed=TRUE)
  rows <- read_tokens("model.txt")
  states <- rows[[1L]][-1L]
  symbols <- rows[[2L]][-1L]
  k <- length(states)
  initial <- as.numeric(rows[[4L]][-1L])
  transition <- do.call(rbind,lapply(rows[seq.int(5L,4L+k)],function(row) as.numeric(row[-(1:2)])))
  emission <- do.call(rbind,lapply(rows[seq.int(5L+k,4L+2L*k)],function(row) as.numeric(row[-(1:2)])))
  model <- make_model("INITIAL",states,symbols,rows[[3L]][2L],initial,transition,emission)
  list(
      model=model,
      sequences=read_tokens("sequences.txt"),
      labeled=read_tokens("labeled.txt"),
      parameters=read_tokens("params.txt")
  )
}
real_text <- function(value,places=4L) {
  if (is.null(value)) return("-")
  text <- sprintf(paste0("%.",places,"f"),value)
  if (startsWith(text,"-") && as.numeric(text) == 0) substring(text,2L) else text
}
model_lines <- function(model) {
  lines <- c(paste("MODEL",model$name),paste("STATES",paste(model$states,collapse=" ")),paste("SYMBOLS",paste(model$symbols,collapse=" ")),
    paste("MISSING",model$missing),paste(
        "INITIAL",
        paste(vapply(model$initial,real_text,character(1)),collapse=" ")
    ))
  for (i in seq_along(model$states)) lines <- c(
      lines,
      paste(
          "TRANSITION",
          model$states[i],
          paste(vapply(model$transition[i,],real_text,character(1)),collapse=" ")
      )
  )
  for (i in seq_along(model$states)) lines <- c(
      lines,
      paste("EMISSION",model$states[i],paste(vapply(model$emission[i,],real_text,character(1)),collapse=" "))
  )
  lines
}
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}

minstd <- function(seed) {
  generator <- new.env(parent=emptyenv())
  generator$state <- as.numeric(seed)
  generator
}
uniform <- function(generator) {
  generator$state <- (48271*generator$state) %% 2147483647
  generator$state/2147483647
}
draw <- function(weights,generator) {
  total <- ordered_sum(weights)
  threshold <- uniform(generator)*total
  cumulative <- 0
  for (i in seq_along(weights)) {
    cumulative <- cumulative+weights[i]
    if (threshold < cumulative) return(i)
  }
  length(weights)
}
synthetic_sequence <- function(model,t_count,generator) {
  states <- observations <- integer(t_count)
  for (t in seq_len(t_count)) {
    weights <- if (t == 1L) model$initial else model$transition[states[t-1L],]
    state <- draw(weights,generator)
    symbol <- draw(model$emission[state,],generator)
    states[t] <- state
    observations[t] <- symbol
  }
  list(states=states,observations=observations)
}
posterior_path <- function(model,forward,generator) {
  t_count <- nrow(forward)
  k <- ncol(forward)
  path <- integer(t_count)
  path[t_count] <- draw(forward[t_count,],generator)
  if (t_count > 1L) for (t in seq.int(t_count-1L,1L)) {
    weights <- vapply(seq_len(k),function(i) forward[t,i]*model$transition[i,path[t+1L]],numeric(1))
    path[t] <- draw(weights,generator)
  }
  path
}

smoothed_model <- function(template,name,initial,transition,emission,alpha) make_model(
    name,
    template$states,
    template$symbols,
    template$missing,
    initial+alpha,
    transition+alpha,
    emission+alpha
)
baum_welch_step <- function(model,sequences,pseudocount) {
  k <- length(model$states)
  m <- length(model$symbols)
  initial <- numeric(k)
  transition <- matrix(0,k,k)
  emission <- matrix(0,k,m)
  for (observations in sequences) {
    result <- forward_backward(model,observations)
    for (i in seq_len(k)) initial[i] <- initial[i]+result$posterior[1L,i]
    for (t in seq_along(observations)) for (i in seq_len(k)) {
      observation <- observations[t]
      if (observation != 0L) emission[i,observation] <- emission[i,observation]+result$posterior[t,i]
      if (t < length(observations)) for (j in seq_len(k)) transition[i,j] <- transition[i,j]+posterior_transition(
          model,
          result,
          t,
          i,
          j
      )
    }
  }
  smoothed_model(model,"BAUM_WELCH",initial,transition,emission,pseudocount)
}
estimate_by_counting <- function(template,pairs,alpha,name="SUPERVISED") {
  k <- length(template$states)
  m <- length(template$symbols)
  initial <- numeric(k)
  transition <- matrix(0,k,k)
  emission <- matrix(0,k,m)
  for (pair in pairs) {
    observations <- pair$observations
    path <- pair$path
    initial[path[1L]] <- initial[path[1L]]+1
    for (t in seq_along(path)) {
      state <- path[t]
      if (observations[t] != 0L) emission[state,observations[t]] <- emission[state,observations[t]]+1
      if (t < length(path)) transition[state,path[t+1L]] <- transition[state,path[t+1L]]+1
    }
  }
  smoothed_model(template,name,initial,transition,emission,alpha)
}
total_loglik <- function(model,sequences) ordered_sum(vapply(
    sequences,
    function(observations) scaled_forward(model,observations)$loglik,
    numeric(1)
))
